package br.com.conectatea.conexao.api; import br.com.conectatea.conexao.domain.*; import br.com.conectatea.conexao.infrastructure.ConexaoRepository; import br.com.conectatea.profissional.infrastructure.ProfissionalRepository; import br.com.conectatea.security.AuthenticatedUser; import jakarta.validation.constraints.NotNull; import java.util.List; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/conexoes") @PreAuthorize("hasRole('PROFISSIONAL')") public class ConexaoController { private final ConexaoRepository connections; private final ProfissionalRepository professionals; public ConexaoController(ConexaoRepository c,ProfissionalRepository p){connections=c;professionals=p;} private Long professional(Authentication a){return professionals.findByUsuarioId(((AuthenticatedUser)a.getPrincipal()).id()).orElseThrow().getId();}
 @PostMapping("/enviar") @ResponseStatus(HttpStatus.CREATED) public Response send(Authentication a,@RequestBody Create r){var me=professional(a);if(me.equals(r.destinatarioId()))throw new IllegalArgumentException("Auto conexão inválida");return Response.from(connections.save(new ConexaoProfissional(me,r.destinatarioId())));}
 @GetMapping public List<Response> list(Authentication a){return connections.findMine(professional(a)).stream().map(Response::from).toList();}
 @PutMapping("/{id}/responder") @Transactional public Response respond(Authentication a,@PathVariable Long id,@RequestBody Reply r){var c=connections.findById(id).orElseThrow();c.respond(professional(a),r.status());return Response.from(c);}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(Authentication a,@PathVariable Long id){var c=connections.findById(id).orElseThrow();if(!c.participant(professional(a)))throw new AccessDeniedException("Não participa da conexão");connections.delete(c);}
 public record Create(@NotNull Long destinatarioId){} public record Reply(@NotNull StatusConexao status){} public record Response(Long id,Long solicitanteId,Long destinatarioId,StatusConexao status){static Response from(ConexaoProfissional c){return new Response(c.getId(),c.getSolicitanteId(),c.getDestinatarioId(),c.getStatus());}}
}
